// Valida al cliente y junta los presupuestos de todos los proveedores
const ev    = $('Llega el pedido').first().json.body || {};
const quien = $('Verificar quien pide').first().json;

function juntar(nodo) {
  try { return $(nodo).all().map(i => i.json).flat().filter(x => x && typeof x === 'object'); }
  catch(e) { return []; }
}

if (!quien || !quien.id) return [{ json: { ok:false, motivo:'sesion' } }];

const sol = juntar('Traer el pedido')[0];
if (!sol) return [{ json: { ok:false, motivo:'pedido' } }];
if (sol.user_id !== quien.id) return [{ json: { ok:false, motivo:'permiso' } }];

const matches = juntar('Traer los matches');
if (!matches.length) return [{ json: { ok:false, motivo:'sin' } }];

const nombres = {};
matches.forEach(m => { nombres[m.id] = (m.proveedores && m.proveedores.nombre) || 'Proveedor'; });

return [{ json: {
  ok: true,
  ids: matches.map(m => m.id).join(','),
  nombres,
  servicio: sol.servicio_necesitado,
  presupuestoCliente: sol.presupuesto
} }];

const ctx = $('Validar').first().json;
if (!ctx.ok) return [{ json: ctx }];

function juntar(nodo) {
  try { return $(nodo).all().map(i => i.json).flat().filter(x => x && typeof x === 'object'); }
  catch(e) { return []; }
}

// uno por proveedor: el más reciente de cada uno
const todos = juntar('Traer presupuestos').filter(p => p.monto);
const porMatch = {};
todos.forEach(p => { if (!porMatch[p.match_id]) porMatch[p.match_id] = p; });
const lista = Object.values(porMatch);

if (lista.length < 2) return [{ json: { ok:false, motivo:'pocos' } }];

const texto = lista.map(p =>
  `id ${p.id} | ${ctx.nombres[p.match_id] || 'Proveedor'} | $${p.monto}\n` +
  `  incluye: ${p.incluye || 'no aclara'}\n` +
  `  plazo: ${p.plazo || 'no aclara'}`
).join('\n\n');

return [{ json: {
  ok: true,
  texto: `Trabajo: ${ctx.servicio}. El cliente había puesto un presupuesto de $${ctx.presupuestoCliente}.\n\nPRESUPUESTOS:\n${texto}`,
  crudos: lista.map(p => ({ id: p.id, matchId: p.match_id, nombre: ctx.nombres[p.match_id] || 'Proveedor',
                            monto: p.monto, estado: p.estado_presupuesto }))
} }];

const ctx = $('Armar comparacion').first().json;
if (!ctx.ok) return [{ json: ctx }];

let r = {};
try { r = JSON.parse($input.first().json.choices[0].message.content.replace(/```json|```/g,'').trim()); }
catch(e) { return [{ json: { ok:false, motivo:'ia' } }]; }

const porId = {};
(Array.isArray(r.items) ? r.items : []).forEach(x => { porId[String(x.id)] = x; });

// Red de seguridad: si la IA pone "sin X" dentro de "incluye", el cliente ve
// un ✓ al lado de algo que NO se hace. Eso se mueve a "no_incluye".
const NEGACION = /^(sin|no incluye)\s+/i;
function separar(inc, no) {
  const si = [], nada = (Array.isArray(no) ? no : []).map(String);
  (Array.isArray(inc) ? inc : []).map(String).forEach(t => {
    const s = t.trim();
    if (NEGACION.test(s)) { const r = s.replace(NEGACION, ''); nada.push(r.charAt(0).toUpperCase() + r.slice(1)); }
    else si.push(s);
  });
  return [si.slice(0,3), nada.slice(0,3)];
}

const items = ctx.crudos.map(c => {
  const x = porId[String(c.id)] || {};
  const [inc, noInc] = separar(x.incluye, x.no_incluye);
  return {
    nombre: c.nombre,
    monto: c.monto,
    estado: c.estado,
    incluye: inc,
    no_incluye: noInc,
    plazo: String(x.plazo || ''),
    etiqueta: String(x.etiqueta || '')
  };
}).sort((a,b) => Number(a.monto) - Number(b.monto));

return [{ json: {
  ok: true,
  items,
  resumen: String(r.resumen || '').slice(0,500),
  ojo: String(r.ojo || '').slice(0,250)
} }];
